args.sparql:
SELECT ?prop ?director WHERE { 
  VALUES ?film { <http://dbpedia.org/resource/Citizen_USA:_A_50_State_Road_Trip> }
  { ?film <http://dbpedia.org/ontology/director> ?director . BIND(<http://dbpedia.org/ontology/director> AS ?prop) }
  UNION
  { ?film <http://dbpedia.org/property/director> ?director . BIND(<http://dbpedia.org/property/director> AS ?prop) }
  UNION
  { ?film <http://dbpedia.org/property/directedBy> ?director . BIND(<http://dbpedia.org/property/directedBy> AS ?prop) }
  UNION
  { ?film <http://dbpedia.org/ontology/creator> ?director . BIND(<http://dbpedia.org/ontology/creator> AS ?prop) }
}

SELECT ?prop ?mother WHERE {
  VALUES ?person { <http://dbpedia.org/resource/Alexandra_Pelosi> }
  { ?person <http://dbpedia.org/ontology/parent> ?mother . BIND(<http://dbpedia.org/ontology/parent> AS ?prop) }
  UNION { ?person <http://dbpedia.org/property/parents> ?mother . BIND(<http://dbpedia.org/property/parents> AS ?prop) }
  UNION { ?person <http://dbpedia.org/property/mother> ?mother . BIND(<http://dbpedia.org/property/mother> AS ?prop) }
  UNION { ?person <http://dbpedia.org/ontology/mother> ?mother . BIND(<http://dbpedia.org/ontology/mother> AS ?prop) }
  UNION { ?person <http://dbpedia.org/property/parent> ?mother . BIND(<http://dbpedia.org/property/parent> AS ?prop) }
}

SELECT DISTINCT ?mother ?motherLabel WHERE {
  VALUES ?film { <http://dbpedia.org/resource/Citizen_USA:_A_50_State_Road_Trip> }
  { ?film <http://dbpedia.org/ontology/director> ?director } UNION { ?film <http://dbpedia.org/property/director> ?director }
  ?director ?p ?mother .
  FILTER(?p IN ( <http://dbpedia.org/ontology/parent> , <http://dbpedia.org/property/parents> ))
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel)='en') }
}

output.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?mother ?motherLabel WHERE {
  VALUES ?film {
    <http://dbpedia.org/resource/Citizen_USA:_A_50_State_Road_Trip>
  }
  {
    ?film dbo:director ?director
  } UNION {
    ?film dbp:director ?director
  }
  ?director ?p ?mother .
  FILTER(?p IN(dbo:parent , dbp:parents))
  OPTIONAL {
    ?mother rdfs:label ?motherLabel .
    FILTER(lang(?motherLabel) = 'en')
  }
}

